import { pagilaExercises } from "@/lib/practice/pagila";
import type { Attempt } from '@/lib/types';

export type ExerciseKind = "sql" | "python" | "quiz" | "written" | "external";
export interface Exercise {
  id: string; skillId: string; title: string; prompt: string; kind: ExerciseKind;
  difficulty: "Foundation" | "Applied" | "Stretch"; minutes: number; starter?: string;
  solution: string; explanation: string; hints: string[]; rubric: string[];
  options?: string[]; correctOption?: number; source?: string;
}
export interface Lesson { id: string; title: string; minutes: number; paragraphs: string[]; example: string; takeaway: string; source: { title: string; url: string }; }
export interface SkillTrack { id: string; title: string; description: string; accent: string; prerequisites: string[]; lessons: Lesson[]; exercises: Exercise[]; }

type LessonInput = [string, string, string, string, string, string];
function lessons(skillId: string, entries: LessonInput[]): Lesson[] { return entries.map(([title, body, example, takeaway, sourceTitle, url], i) => ({ id: `${skillId}-lesson-${i + 1}`, title, minutes: 7 + i * 2, paragraphs: body.split("\n\n"), example, takeaway, source: { title: sourceTitle, url } })); }
function quiz(skillId: string, title: string, prompt: string, options: string[], correctOption: number, explanation: string): Exercise { return { id: `${skillId}-${title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`, skillId, title, prompt, kind: "quiz", difficulty: "Foundation", minutes: 5, solution: options[correctOption], explanation, options, correctOption, hints: ["State the grain or intended decision before picking an answer."], rubric: [] }; }
function written(skillId: string, title: string, prompt: string, solution: string, rubric: string[], external = false): Exercise { return { id: `${skillId}-${title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`, skillId, title, prompt, kind: external ? "external" : "written", difficulty: "Applied", minutes: 20, solution, explanation: "Compare your work with each criterion. Written and external work is self-reviewed; the app does not claim to execute or automatically grade it.", hints: ["Write assumptions and the audience's decision first.", "Work a tiny example by hand, including a missing or duplicated record.", "Use the rubric to test your approach before reviewing the reference."], rubric }; }
const rubric = ["Define the grain, assumptions, and intended decision.", "Give a concrete worked example and explain the tradeoff.", "Include a check that would expose an incorrect result."];

export const tracks: SkillTrack[] = [
  { id: "sql", title: "SQL & PostgreSQL", description: "Recover fluency in joins, windows, grain, and validation.", accent: "blue", prerequisites: [], lessons: lessons("sql", [
    ["Grain and missing matches", "A row is a business event or entity at a particular level of detail. A film title, physical inventory copy, rental event, and payment transaction have different grains. State the intended output grain before writing SELECT.\n\nAn inner join retains matched pairs. A left join preserves unmatched left rows, so COUNT(*) may include a placeholder while COUNT(payment_id) ignores its null. Many-to-many joins multiply rows; DISTINCT is only correct when distinct entities are the intended measure.", "SELECT c.customer_id, COUNT(p.payment_id) AS payments\nFROM customer c LEFT JOIN payment p USING (customer_id)\nGROUP BY c.customer_id;", "Predict cardinality and test a customer with no payment.", "PostgreSQL: table expressions", "https://www.postgresql.org/docs/current/queries-table-expressions.html"],
    ["Aggregations and window functions", "GROUP BY collapses rows to the grouping grain. Window functions calculate across related rows while retaining each row. DENSE_RANK preserves equal revenue ranks; ROW_NUMBER selects exactly one row when paired with a deterministic tie-breaker.\n\nFor month-over-month metrics, aggregate to month first and then apply LAG. NULLIF prevents division by zero. LAG compares existing rows, so insert a calendar scaffold if the business definition requires missing months.", "WITH monthly AS (\n SELECT date_trunc('month', payment_date) AS month, SUM(amount) revenue\n FROM payment GROUP BY 1\n)\nSELECT *, LAG(revenue) OVER (ORDER BY month) previous_revenue FROM monthly;", "Aggregate to the metric grain, then use the window.", "PostgreSQL: window functions", "https://www.postgresql.org/docs/current/tutorial-window.html"],
    ["Validate independently", "A plausible answer can still be wrong. Reconcile revenue against a direct payment total, inspect join counts, and test missing parents. Aggregate actor counts separately from payment revenue before joining both to films.\n\nSUM(DISTINCT amount) removes repeated values, not duplicated business events: two legitimate payments of 4.99 must both count. Historical inactivity should use the latest event in the dataset, not today's clock.", "WITH revenue AS (\n SELECT i.film_id, SUM(p.amount) revenue\n FROM payment p JOIN rental r USING (rental_id)\n JOIN inventory i USING (inventory_id) GROUP BY i.film_id\n) SELECT * FROM revenue;", "Use checks with different failure modes, not the same join twice.", "PostgreSQL: aggregate functions", "https://www.postgresql.org/docs/current/functions-aggregate.html"],
  ]), exercises: pagilaExercises },
  { id: "modeling", title: "Data modeling & warehouses", description: "Design useful facts, dimensions, and trustworthy history.", accent: "violet", prerequisites: ["sql"], lessons: lessons("modeling", [
    ["A star starts with the business process", "Choose the business process, declare the fact grain, then identify dimensions and measures. A sales-line fact describes one order line, not an order and not a customer. Dimensions provide filtering and grouping; facts record observations.\n\nSeparate facts with incompatible grains. Joining a daily inventory snapshot directly to transaction lines can multiply balances. Conformed dimensions let facts be compared after each has been aggregated appropriately.", "FactSales(order_line_key, date_key, customer_key, product_key, quantity, net_amount)\nDimProduct(product_key, product_id, category)", "Write one sentence defining a fact row before choosing columns.", "Microsoft: star schema guidance", "https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"],
    ["History and surrogate keys", "A natural key identifies an entity in its source; a surrogate key identifies a warehouse dimension version. Type 1 changes overwrite history. Type 2 adds a new row with an effective interval and a new surrogate key.\n\nFor a historical fact, look up the version valid at the event time. Use non-overlapping half-open intervals and handle late-arriving facts explicitly. Unknown members preserve facts whose dimension lookup has not arrived.", "customer_key=41, customer_id='C7', segment='SMB', valid_from='2025-01-01', valid_to='2026-03-01'\ncustomer_key=82, customer_id='C7', segment='Enterprise', valid_from='2026-03-01', valid_to=NULL", "A current-state join cannot reconstruct historical segmentation.", "Microsoft: dimension tables", "https://learn.microsoft.com/en-us/fabric/data-warehouse/dimensional-modeling-dimension-tables"],
    ["Additivity and semantic contracts", "Revenue is usually additive across dates and products; a balance is not additive across time; a ratio should usually be recomputed from its numerator and denominator. Define eligible records, timezone, currency, and late corrections with the metric.\n\nA date dimension makes fiscal periods and missing-day reporting explicit. Validate uniqueness on dimension keys, expected fact counts, and reconciled totals before optimizing performance.", "Conversion rate = SUM(converted_sessions) / SUM(eligible_sessions)\nNot: AVERAGE(daily_conversion_rate)", "Metric definitions belong beside their model and validation.", "Microsoft: fact tables", "https://learn.microsoft.com/en-us/fabric/data-warehouse/dimensional-modeling-fact-tables"],
  ]), exercises: [
    quiz("modeling", "Choose the fact grain", "You need quantities and discounts by product within an order. What should one fact row represent?", ["One customer", "One order line", "One order month"], 1, "An order line retains product-level measures without mixing order and line grains."),
    quiz("modeling", "Historical segment", "Revenue must use the customer's segment at purchase time. Which design preserves this?", ["Overwrite segment on every load", "Use the latest segment for all facts", "Type 2 dimension with event-time lookup"], 2, "A versioned dimension key on the fact preserves the historical segment."),
    quiz("modeling", "Aggregate a ratio", "Two stores convert 1/2 and 90/100 sessions. What combined calculation is valid?", ["(1 + 90) / (2 + 100)", "Average 50% and 90%", "Sum the two percentages"], 0, "Sum eligible numerators and denominators; an unweighted average gives small stores undue influence."),
    written("modeling", "Model rental revenue", "Design a star for rental revenue and film demand. Declare facts, grains, dimensions, and non-additive measures.", "Use payment transaction grain for revenue and rental event grain for demand. Share date, film, store, customer dimensions. Attribute store explicitly; keep inventory snapshot supply separate.", rubric),
    written("modeling", "Late-arriving customer", "A payment arrives before its customer dimension row. Explain loading, recovery, and history behavior.", "Load against an unknown member while retaining the natural key. Backfill the appropriate version on arrival; make reconciliation and reprocessing idempotent. Avoid losing the payment through an inner join.", rubric),
    written("modeling", "Review a mixed-grain model", "A table joins order lines to daily inventory and sums inventory balance by month. Diagnose the errors and propose a replacement.", "The join repeats stock across lines; summing snapshots across time is invalid. Keep inventory at product-store-day grain, summarize each fact separately, and use a period-end or average balance defined by the business.", rubric),
  ] },
  { id: "etl", title: "ETL, ELT & data quality", description: "Build repeatable pipelines and make failures observable.", accent: "teal", prerequisites: ["sql", "modeling"], lessons: lessons("etl", [
    ["Raw, staged, and modeled", "Preserve source records in a raw layer, standardize types and names in staging, then build business models. ETL transforms before loading; ELT transforms within the analytical destination. Choose based on access, scale, and governance rather than acronym preference.\n\nRecord source timestamps and ingestion time separately. Retain enough lineage to trace a reported figure back to source records without putting secrets or personal fields in logs.", "raw_orders → stg_orders (types, dedupe) → fct_order_lines (business grain)\nChecks: unique line_id; non-null order_id; amount reconciliation", "Keep source fidelity separate from business interpretation.", "dbt: model organization", "https://docs.getdbt.com/best-practices/how-we-structure/1-guide-overview"],
    ["Incremental and idempotent loads", "An incremental load processes changed records instead of rebuilding everything. A watermark alone can miss late updates; use an overlap window or source change tracking. An idempotent load produces the same final state when replayed.\n\nUpsert by a stable business key and persist the watermark only after a successful transaction. Handle deletions according to source semantics rather than assuming missing rows were deleted.", "Read updated_at >= last_success - 2 days\nDeduplicate by order_line_id and latest updated_at\nMERGE/upsert → commit → advance watermark", "A retry should repair or repeat work without duplicating it.", "dbt: incremental models", "https://docs.getdbt.com/docs/build/incremental-models"],
    ["Quality gates and incident response", "Test uniqueness, non-null keys, referential integrity, valid ranges, and freshness. Some anomalies should block publishing; others need an alert and investigation. A zero-row source might be a legitimate quiet day or a broken extract.\n\nA useful incident includes impact, affected time range, last good run, owner, and a reprocessing plan. Reconcile counts and amounts after recovery, not just job success.", "Gate: duplicate payment_id = 0\nWarn: daily row count outside expected range\nMonitor: max(source_updated_at) age, load duration, rejected rows", "Technical success does not establish business correctness.", "dbt: data tests", "https://docs.getdbt.com/docs/build/data-tests"],
  ]), exercises: [
    quiz("etl", "Safe retry", "A network failure happens after loading records but before acknowledging success. What prevents duplicates on retry?", ["Append every record again", "Upsert by stable keys within a transaction", "Skip the next run"], 1, "Stable keys and atomic upsert make repeated processing idempotent."),
    quiz("etl", "Late updates", "Yesterday's order is corrected today. Which incremental strategy can capture it?", ["Filter only by original order date", "Only process newly created IDs", "Use updated_at with a replay overlap"], 2, "A change timestamp plus overlap can capture late edits; deduplication makes overlap safe."),
    quiz("etl", "Quality severity", "Which issue should block publication of a payment fact?", ["A duplicated transaction key", "A newly seen valid category", "A small but explainable volume change"], 0, "Duplicate transaction keys compromise grain and revenue. Other cases need business context."),
    written("etl", "Design a daily load", "Specify a daily payment pipeline: extraction, watermark, staging, deduplication, publishing, and retry.", "Store raw batches, use updated timestamps with overlap, dedupe stable payment IDs, validate grain and amounts, atomically publish, then persist success and watermark. Replays must leave the same final state.", rubric),
    written("etl", "Reconcile a missing day", "A load reports success but revenue is zero for Tuesday. Give a prioritized investigation and recovery plan.", "Check source freshness and filters, extraction counts, timezone boundaries, rejected records, and upstream incidents. Compare last good run, reprocess the affected window, then reconcile counts and sums with the source.", rubric),
    written("etl", "Design quality checks", "List five tests for a customer and payment model, separating blocking failures from warnings.", "Block null/duplicate payment keys, invalid required customer references, and incompatible currency or amount types. Alert on freshness and abnormal volume using agreed thresholds. Record ownership and affected rows.", rubric),
  ] },
  { id: "powerbi", title: "Power BI & DAX", description: "Refresh context, measures, models, and business dashboards.", accent: "amber", prerequisites: ["modeling"], lessons: lessons("powerbi", [
    ["Relationships before visuals", "Use dimensions to filter facts through one-to-many relationships, with a unique dimension-side key. Prefer a clear star and single-direction filters unless a specific requirement justifies more complex behavior.\n\nA visual cannot repair duplicated business events in the model. Check unmatched dimension keys, auto-created relationships, and date coverage. Use explicit measures for business metrics.", "DimDate[Date] 1 → * FactSales[OrderDate]\nDimProduct[ProductKey] 1 → * FactSales[ProductKey]\nRevenue = SUM(FactSales[NetAmount])", "Model quality determines whether slicers tell a coherent story.", "Microsoft: Power BI relationships", "https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-relationships-understand"],
    ["Filter context and CALCULATE", "A measure is evaluated in filter context from slicers, visuals, and DAX. Row context describes the current row of an iterator or calculated column. CALCULATE changes filter context; context transition converts an existing row context into filters.\n\nUse DIVIDE for ratio behavior at zero denominators. Decide whether a denominator should remove a category filter, retain date filters, or respect all selections.", "Revenue = SUM(Sales[Revenue])\nMargin % = DIVIDE(SUM(Sales[Profit]), [Revenue])\nAll Product Revenue = CALCULATE([Revenue], REMOVEFILTERS(Product))", "Explain exactly which filters a denominator retains.", "Microsoft: CALCULATE", "https://learn.microsoft.com/en-us/dax/calculate-function-dax"],
    ["Time intelligence and verification", "Use a contiguous date table that spans the required reporting period. Distinguish prior month, prior year, year-to-date, and rolling windows; each answers a different question.\n\nTest measures in a table before composing a dashboard. Validate totals, filtered subsets, empty selections, and no-comparison periods. Screen captures support visual review; they do not prove the entire model is correct.", "Revenue YTD = TOTALYTD([Revenue], 'Date'[Date])\nRevenue PY = CALCULATE([Revenue], SAMEPERIODLASTYEAR('Date'[Date]))\nYoY % = DIVIDE([Revenue] - [Revenue PY], [Revenue PY])", "Validate blank and total behavior as deliberately as normal rows.", "Microsoft: date tables", "https://learn.microsoft.com/en-us/power-bi/guidance/model-date-tables"],
  ]), exercises: [
    quiz("powerbi", "Measure or column", "Revenue must react to date and product slicers. Which is the best default?", ["A calculated column repeating total revenue", "An explicit SUM measure", "A static text box"], 1, "Measures recalculate in the active filter context."),
    quiz("powerbi", "Safe percentage", "Which DAX expression handles a zero denominator using DAX's standard ratio function?", ["SUM(Sales[Profit]) + [Revenue]", "DIVIDE(SUM(Sales[Profit]), [Revenue])", "AVERAGE(Sales[Profit])"], 1, "DIVIDE returns blank by default when its denominator is zero or blank."),
    quiz("powerbi", "Filter direction", "What is the simplest default relationship from Product to Sales?", ["Many-to-many, bidirectional", "No relationship", "One-to-many, dimension filtering fact"], 2, "A unique dimension key and single-direction filtering reduce ambiguity."),
    written("powerbi", "Build a sales dashboard", "Download the synthetic CSV dataset below. In Power BI Desktop, create a star model, revenue/profit/margin measures, month trend, category comparison, and slicers. Save evidence in Portfolio.", "Use OrderDate, Product and Region dimensions or documented equivalents. Reconcile revenue and profit to CSV totals; ensure margin is total profit / total revenue. Show at least one empty selection behavior.", ["Declare sales-line grain and verify keys.", "Revenue, profit, and margin reconcile to the source.", "Date/category slicers interact consistently and labels explain currency.", "Attach screenshots and describe one decision the report supports."], true),
    written("powerbi", "Diagnose an inflated total", "A Power BI report shows twice the source revenue after adding a category bridge. Explain the model and validation changes.", "Inspect bridge multiplicity and relationship directions. Do not divide the measure by two. Restore transaction grain, model category allocation deliberately, and reconcile both totals and filtered subsets.", rubric),
    written("powerbi", "DAX context walkthrough", "Write a category share measure that removes product/category filters while retaining the date selection. Explain row and grand-total behavior.", "DIVIDE([Revenue], CALCULATE([Revenue], REMOVEFILTERS(Product))). This assumes category lives in Product; adapt if there is a separate dimension. Date remains filtered. The grand total is normally 100% for the retained context.", rubric),
  ] },
  { id: "excel", title: "Power Query & Excel", description: "Clean repeatably and verify spreadsheet logic.", accent: "green", prerequisites: [], lessons: lessons("excel", [
    ["A repeatable query", "Power Query transformations form a refreshable sequence. Set explicit column types, normalize keys, and retain an audit path for removed or invalid rows. An applied step should explain a transformation, not conceal a manual fix.\n\nPromoting headers and type detection can behave differently when source files change. Check schema and null counts after refresh; avoid hard-coded row positions for business rules.", "Source → Promote headers → Set types → Trim keys → Keep valid rows → Group\nM example: Table.TransformColumnTypes(Source, {{\"Amount\", type number}})", "Make cleaning rules reproducible and inspect rejected rows.", "Microsoft: Power Query best practices", "https://learn.microsoft.com/en-us/power-query/best-practices"],
    ["Merge, append, and folding", "Append stacks compatible rows. Merge joins tables by keys and can multiply records when the lookup key is not unique. Check lookup uniqueness and match coverage before expanding merged columns.\n\nQuery folding pushes supported transformations to the source. Filter early where it preserves semantics and inspect folding behavior rather than assuming every step is pushed down.", "Append January + February sales.\nMerge sales with one row per ProductID; validate count before/after expansion.\nAnti-join reveals missing product keys.", "A merge is a relational join with the same grain risks as SQL.", "Microsoft: query folding", "https://learn.microsoft.com/en-us/power-query/power-query-folding"],
    ["Formulas and auditability", "Use structured table references so formulas expand with new rows. XLOOKUP finds matching keys; SUMIFS aggregates under multiple conditions. Distinguish a missing key from a legitimate zero and avoid hiding all errors with IFERROR.\n\nReconcile a pivot or summary against an independent SUM. Test duplicate keys, blanks, unexpected text amounts, and new categories before publishing.", "=XLOOKUP([@ProductID], Products[ProductID], Products[Category], \"Missing product\")\n=SUMIFS(Sales[Revenue], Sales[Region], A2)", "An error label can reveal a data problem that a zero would hide.", "Microsoft: XLOOKUP", "https://support.microsoft.com/en-us/office/xlookup-function-b7fd680e-6d10-43e6-84f9-88eae8bf5929"],
  ]), exercises: [
    quiz("excel", "Append or merge", "Combine January and February files with the same columns into one table.", ["Append", "Merge on row number", "Pivot"], 0, "Append stacks rows; merge adds related columns using keys."),
    quiz("excel", "Lookup duplication", "A lookup has two rows for one ProductID. What can happen after merging and expanding?", ["The source rows may multiply", "Power Query always deduplicates", "Only the first row is guaranteed"], 0, "A merge returns all matching rows; validate lookup uniqueness."),
    quiz("excel", "Missing versus zero", "A price lookup is missing. Which output best supports data quality investigation?", ["Silently return 0", "Return an explicit Missing price indicator", "Remove the entire order"], 1, "Missing and zero have different meaning and should stay distinguishable."),
    written("excel", "Refreshable sales workbook", "Download the sales CSV. Build a typed Power Query import and a monthly/category summary that survives adding rows.", "Use an Excel table or refreshable connection, explicit dates/numbers, a PivotTable or SUMIFS, and reconciliation totals. Track rejected records and demonstrate refresh with one additional row.", rubric, true),
    written("excel", "Investigate a merge", "A 1,000-row sales table becomes 1,080 rows after merging a product table. Diagnose and fix without dropping legitimate sales.", "Count duplicate lookup keys, inspect matches per sale, define a current product record or model history using dates. Fix the lookup grain and reconcile sales IDs and amounts.", rubric),
    written("excel", "Formula audit", "Design three checks for a workbook using XLOOKUP prices and SUMIFS regional totals. Include a duplicate key and missing price.", "Check price-key uniqueness, count explicit missing matches, and reconcile regional sums to total sales. Use known hand-calculated rows and verify added rows extend formulas.", rubric),
  ] },
  { id: "qlik", title: "Qlik Sense", description: "Refresh associative models, loading, and set analysis.", accent: "rose", prerequisites: ["modeling"], lessons: lessons("qlik", [
    ["Associations and keys", "Qlik associates tables through fields with matching names. A shared name is therefore a modeling choice, not just a label. Multiple shared fields can create synthetic keys; circular references make relationships difficult to interpret.\n\nChoose deliberate keys, rename unrelated fields, and use link tables or concatenation when appropriate to the grain. Inspect the model viewer and selection behavior after loading.", "Sales: LOAD OrderID, ProductID, Revenue FROM ...;\nProducts: LOAD ProductID, Category FROM ...;\nRename unrelated Name fields to CustomerName and ProductName.", "Control field names so associations reflect business relationships.", "Qlik: synthetic keys", "https://help.qlik.com/en-US/sense/November2025/Subsystems/Hub/Content/Sense_Hub/Scripting/synthetic-keys.htm"],
    ["Load script and mapping", "The load script shapes data before it enters the associative model. Resident loads reuse an already loaded table. Mapping tables support key-value lookup through ApplyMap without introducing an ordinary association.\n\nUse an explicit default for missing mappings. Validate row counts and uniqueness around joins; a left join can multiply rows just as it does in SQL.", "CategoryMap: MAPPING LOAD ProductID, Category FROM ...;\nSales: LOAD *, ApplyMap('CategoryMap', ProductID, 'Unknown') AS Category FROM ...;", "Decide whether a lookup belongs in a mapping or a separate dimension.", "Qlik: ApplyMap", "https://help.qlik.com/en-US/sense/November2025/Subsystems/Hub/Content/Sense_Hub/Scripting/MappingFunctions/ApplyMap.htm"],
    ["Selections and set analysis", "Ordinary aggregations use current selections. Set analysis specifies a set of records, often modifying selected fields. A year modifier fixes the year while retaining other selections; the identifier 1 starts from the full record set.\n\nExplain the desired selection behavior before writing a set expression. Test the measure under no selection, conflicting year selection, and a product selection.", "Sum({$<Year={2026}>} Revenue)\nSum({1} Revenue)\nThe second ignores current selections; the first modifies Year only.", "A set expression is a business definition of which records count.", "Qlik: set analysis", "https://help.qlik.com/en-US/sense/November2025/Subsystems/Hub/Content/Sense_Hub/ChartFunctions/SetAnalysis/set-analysis-expressions.htm"],
  ]), exercises: [
    quiz("qlik", "Unexpected association", "Customer and Product tables each contain Name. Why rename these fields?", ["Names are always invalid", "Matching field names create associations", "Qlik cannot load text"], 1, "Qlik links matching field names; unrelated names can associate incorrectly."),
    quiz("qlik", "Mapping purpose", "What is ApplyMap suitable for?", ["A deliberate key-to-value lookup", "Executing a DAX measure", "Enforcing a relational foreign key"], 0, "ApplyMap reads a mapping table and supports a default for unmatched keys."),
    quiz("qlik", "All selections", "Which identifier starts a set expression from the full record set?", ["$", "1", "Year"], 1, "1 denotes the full set, whereas $ denotes current selections."),
    written("qlik", "Repair synthetic keys", "Orders and Returns share CustomerID, ProductID, and Date. Explain why a synthetic key may arise and propose a model by grain.", "Identify intended fact grains and relationships first. Use deliberate composite keys/link tables or concatenate compatible events. Rename fields that should not associate. Validate counts and selection behavior; do not blindly remove all keys.", rubric),
    written("qlik", "Write a mapping load", "Write a load-script sketch mapping ProductID to Category with an explicit Unknown fallback. Explain duplicate mapping-key treatment.", "Create a two-column MAPPING LOAD, then ApplyMap('CategoryMap', ProductID, 'Unknown'). Resolve duplicate product mapping keys in preparation rather than depending on accidental source order.", rubric),
    written("qlik", "Explain selection behavior", "Compare Sum(Revenue), Sum({$<Year={2026}>} Revenue), and Sum({1} Revenue) when Year=2025 and Product=A are selected.", "The first uses 2025 and A. The second replaces the year selection with 2026 while retaining Product=A. The third ignores current selections. Test against tiny known records and name the KPI accordingly.", rubric),
  ] },
  { id: "python", title: "Python & pandas", description: "Explore, transform, test, and communicate with code.", accent: "sky", prerequisites: [], lessons: lessons("python", [
    ["Inspect before transforming", "Read the schema, types, null counts, and a few rows before changing a DataFrame. A number stored as text behaves differently from numeric data, and silently coercing invalid values can lose information.\n\nUse explicit date conversion and key checks. Keep the input immutable where practical so the cleaning result can be compared with the original.", "df.info()\ndf.isna().sum()\nclean = df.assign(amount=pd.to_numeric(df['amount'], errors='coerce'))\ninvalid = clean.loc[clean['amount'].isna()]", "Track how many rows are changed, rejected, or missing.", "pandas: introductory tutorials", "https://pandas.pydata.org/docs/getting_started/intro_tutorials/index.html"],
    ["Group, merge, and reshape", "Groupby reduces records to the requested grouping grain. A merge can multiply rows when keys are duplicated on both sides; validate='many_to_one' asserts an expected lookup relationship.\n\nKeep missing groups deliberately with dropna=False when that matches the question. Reconcile grouped totals to the ungrouped total and inspect unmatched merge keys.", "summary = df.groupby('region', dropna=False)['revenue'].sum()\njoined = sales.merge(products, on='product_id', how='left', validate='many_to_one', indicator=True)", "Use validation arguments as executable statements of grain.", "pandas: merge", "https://pandas.pydata.org/docs/reference/api/pandas.DataFrame.merge.html"],
    ["Functions, tests, and charts", "Small pure functions are easier to test than notebooks with hidden state. Test empty input, missing values, duplicated keys, and zero denominators. For a ratio, aggregate numerator and denominator separately before dividing.\n\nUse charts to answer a question with honest axes and labels. Separate observed associations from causal claims. The practice runner provides synthetic data and supports pandas and matplotlib in a browser worker.", "def safe_rate(successes, trials):\n    return None if trials == 0 else successes / trials\nassert safe_rate(0, 0) is None\nassert safe_rate(1, 4) == 0.25", "Test behavior and counterexamples, not one remembered output.", "Python: unittest", "https://docs.python.org/3/library/unittest.html"],
  ]), exercises: [] },
  { id: "metrics", title: "Metrics, statistics & dashboard UX", description: "Choose sound metrics and make the decision clear.", accent: "orange", prerequisites: [], lessons: lessons("metrics", [
    ["A metric needs a contract", "Name the entity, eligible population, time window, timezone, and exclusions. A conversion rate could mean sessions, people, or accounts; changing the denominator changes the question.\n\nBreak a headline metric into drivers and guardrails. A faster conversion can coincide with more refunds; a dashboard should expose that tradeoff rather than maximize a number in isolation.", "Signup conversion = distinct eligible visitors completing signup / distinct eligible visitors\nWindow: same calendar week; exclude internal traffic; deduplicate by visitor key.", "Define the denominator before interpreting the numerator.", "Google Analytics: dimensions and metrics", "https://support.google.com/analytics/answer/9143382"],
    ["Variation and inference", "Samples vary. A small observed improvement may reflect noise, seasonality, selection, or instrumentation changes. Confidence intervals describe uncertainty under assumptions; a p-value is not the probability that a hypothesis is true.\n\nRandomization helps identify causal effects when implementation and analysis are sound. Check assignment units, exposure, sample-ratio mismatch, and guardrails before announcing a winner.", "A: 50/1000 conversions; B: 60/1000 conversions\nObserved lift: 1 percentage point, or 20% relative.\nThis alone does not establish a reliable causal improvement.", "Report effect size, uncertainty, and assumptions together.", "NIST: statistical inference", "https://www.itl.nist.gov/div898/handbook/prc/prc.htm"],
    ["Visual hierarchy and honest comparison", "Choose a chart for the comparison: line for time, bar for categories, scatter for relationships. Use units and descriptive labels, limit color to meaningful differences, and make important context visible.\n\nBar charts generally need a zero baseline because length encodes magnitude. Explain incomplete periods, missing data, and changed definitions. Add accessible text and avoid encoding meaning through color alone.", "Title: Revenue fell 8% as returning-customer orders slowed\nContext: completed weeks, constant currency\nViews: weekly line + new/returning breakdown + data freshness", "The headline should help the audience decide what to investigate next.", "Microsoft: accessible report design", "https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-accessibility-creating-reports"],
  ]), exercises: [
    quiz("metrics", "Relative and absolute lift", "Conversion rises from 5% to 6%. What is correct?", ["1 percentage point and 20% relative lift", "1% relative lift", "20 percentage points"], 0, "The absolute change is 6%-5%=1 point. Relative change is 1/5=20%."),
    quiz("metrics", "Weighted conversion", "Monday is 1/10 and Tuesday is 90/100. What is the overall conversion?", ["50%", "91/110", "100%"], 1, "Combine eligible events: 91 conversions out of 110 opportunities."),
    quiz("metrics", "Causal claim", "Revenue rose after a dashboard launched. What can you conclude from this alone?", ["The dashboard caused the rise", "Every user benefited", "There is a temporal association requiring further evidence"], 2, "Seasonality and other changes may explain the rise. Timing alone does not establish causality."),
    written("metrics", "Define an activation metric", "Define activation for an AI assistant product. Specify entity, qualifying behavior, time window, denominator, and one guardrail.", "For example, account activation within seven days: new eligible accounts completing a successful core workflow / new eligible accounts with seven days of observation. Guardrail: failures or low-rated results. State exclusions and late-event treatment.", rubric),
    written("metrics", "Dashboard critique", "A revenue chart uses a truncated bar axis, no currency label, and a partial current month. Rewrite its presentation and describe the risk in each choice.", "Use a zero baseline for bars or a labeled line for trend, show currency and definition, and mark or exclude partial periods. Compare matching elapsed periods only under an explicit rule. Add freshness and a descriptive takeaway.", rubric),
    written("metrics", "Evaluate an experiment", "Variant B converts 60/1000 versus 50/1000 for A. Describe what else you need before recommending rollout.", "Check random assignment, exposure unit, tracking quality, planned duration/sample size, uncertainty, practical effect, segment stability, and guardrails. Report 1 point absolute and 20% relative lift without declaring significance from counts alone.", rubric),
  ] },
  { id: "git-ai", title: "Git & AI-assisted development", description: "Ship explainable changes and verify generated work.", accent: "indigo", prerequisites: [], lessons: lessons("git-ai", [
    ["Changes you can review", "Git records snapshots. Inspect the working tree, stage only intended changes, and use a focused commit that explains the outcome. A branch isolates a line of development but does not make uncommitted changes safe by itself.\n\nReview diffs for credentials, generated noise, and unrelated edits. Reproduce a bug before a fix and run checks that exercise its failure mode.", "git status\ngit diff\ngit add path/to/changed-file\ngit diff --cached\ngit commit -m \"Fix revenue double counting\"", "A reviewer should be able to trace each changed line to the request.", "Git: recording changes", "https://git-scm.com/book/en/v2/Git-Basics-Recording-Changes-to-the-Repository"],
    ["Ask AI for verifiable work", "Give an assistant the goal, current behavior, constraints, examples, and a definition of done. Ask it to inspect existing patterns before editing. Keep secrets and private source data out of public prompts.\n\nGenerated code and SQL are hypotheses. Validate outputs against independent fixtures and document assumptions. An explanation that sounds confident does not replace running the query.", "Goal: one row per customer including non-payers.\nConstraint: PostgreSQL, existing schema, no production changes.\nCheck: duplicated payment values, customer without payments, tied ranks.", "Specify observable behavior and counterexamples.", "GitHub: responsible use of Copilot", "https://docs.github.com/en/copilot/responsible-use/copilot-code-completion"],
    ["Recover safely and communicate", "A revert creates a new commit undoing an earlier commit and preserves shared history. Reset changes branch or staging state and can discard work depending on its mode. Choose recovery based on whether history is shared.\n\nA useful change description states the problem, resulting behavior, and checks run. Include limitations honestly. Resolve conflicts by understanding both intended behaviors rather than selecting a side blindly.", "git revert <shared-bad-commit>\nPR: Prevent actor joins from multiplying payments.\nValidation: totals reconcile; film with two actors; two equal payments.", "Prefer recoverable actions and clear evidence of correctness.", "Git: revert", "https://git-scm.com/docs/git-revert"],
  ]), exercises: [
    quiz("git-ai", "Review the staged snapshot", "Which command shows exactly the staged changes before a commit?", ["git diff --cached", "git log --oneline", "git fetch"], 0, "The cached/staged diff shows what the next commit will include."),
    quiz("git-ai", "Undo a shared commit", "A bad commit has been shared with teammates. What is the usual history-preserving undo?", ["Delete the repository", "git revert", "Force reset the shared branch without coordination"], 1, "Revert records a new inverse commit, preserving shared history."),
    quiz("git-ai", "AI query verification", "An AI query returns a plausible revenue total. What is strongest evidence before using it?", ["Its explanation sounds confident", "It uses many CTEs", "Independent reconciliation and edge-case tests"], 2, "Correctness requires checking behavior and business definitions independently."),
    written("git-ai", "Write a useful AI prompt", "Draft a prompt asking an assistant to fix an inflated payment query. Include constraints and acceptance checks.", "Specify payment grain, schema paths, preservation of legitimate equal amounts, no production writes, and tests for two actors, equal-valued payments, and unmatched entities. Ask for inspection, minimal changes, and total reconciliation.", rubric),
    written("git-ai", "Review a generated diff", "An assistant fixes a DAX measure while renaming unrelated files and adding an API key to a config. Describe the review and correction.", "Reject the exposed credential and rotate it if shared; keep secrets server-side. Remove unrelated changes, inspect the measure's context behavior, and run focused totals/slicer checks. Keep the change tied to the original issue.", rubric),
    written("git-ai", "Write a change description", "Write a concise PR description for a fix that preaggregates film revenue before joining actors.", "Payments were repeated once per actor, inflating revenue. Aggregate revenue and actor counts separately at film grain before joining. Validate a multi-actor film, equal-valued legitimate payments, empty films, and total reconciliation.", rubric),
  ] },
  { id: "communication", title: "Stakeholders & technical explanation", description: "Turn ambiguous requests into useful, credible decisions.", accent: "cyan", prerequisites: [], lessons: lessons("communication", [
    ["Clarify the decision", "Start with who will use the result, which decision it supports, and what action could change. Clarify metric definitions, audience, timing, and acceptance examples before selecting visuals or implementation.\n\nRestate ambiguity as alternatives with practical consequences. Record agreed assumptions and examples so a stakeholder can verify the result without reading code.", "Request: Which store performs best?\nClarify: revenue, margin, utilization, or growth?\nStore definition: customer home, staff home, or inventory origin?", "A precise question prevents a technically correct answer to the wrong problem.", "Microsoft: BI solution planning", "https://learn.microsoft.com/en-us/power-bi/guidance/powerbi-implementation-planning-bi-strategy-bi-solution-planning"],
    ["Explain with evidence", "Lead with the finding or recommendation, then give evidence and the practical limit. Explain grain and assumptions in business language. Distinguish what the data shows from what it cannot establish.\n\nA short worked example is often clearer than a list of implementation details. If a result is uncertain, state the unknown and the next check that would resolve it.", "Revenue was overstated because each payment repeated for every actor. Counting revenue once per payment lowers the total to the reconciled source amount. Film popularity still needs a separate demand measure.", "Connect the technical mechanism to its business consequence.", "Google: technical writing", "https://developers.google.com/tech-writing/one"],
    ["Experience stories and incidents", "Describe a concrete situation, your responsibility, the action you personally took, and the observed result. Do not convert a prototype or synthetic exercise into a production impact claim.\n\nFor an incident, communicate impact, current status, workaround, next update, and prevention. Blame is less useful than a reproducible cause and a verified recovery.", "Situation: report totals differed from finance.\nAction: traced payment grain and reproduced actor multiplication.\nResult: totals reconciled in the test dataset; production impact requires evidence.", "Be specific about your contribution and the evidence behind outcomes.", "Google SRE: postmortem culture", "https://sre.google/sre-book/postmortem-culture/"],
  ]), exercises: [
    quiz("communication", "First stakeholder question", "A stakeholder asks for a dashboard. What should you establish first?", ["Which gradient to use", "The decision, audience, and success criteria", "How many charts fit"], 1, "The intended decision determines metrics, required data, and useful presentation."),
    quiz("communication", "Evidence boundary", "You improved a synthetic portfolio query. Which claim is supported?", ["Saved the company millions", "Proved every production metric is correct", "Reconciled results on documented synthetic cases"], 2, "Describe demonstrated evidence without inventing business impact."),
    quiz("communication", "Incident update", "Which update is most useful while investigating stale data?", ["Impact, last good data, workaround, next update", "A long list of every command", "Everything is fine because the job exited successfully"], 0, "Users need practical impact and a dependable next update."),
    written("communication", "Clarify store performance", "Draft five focused questions for a manager asking which store performs best. Include a proposed default definition.", "Ask the decision, performance metric, store attribution, period/comparison, and eligible population. Propose inventory-store net revenue for completed periods with returns treatment stated, then confirm suitability for the decision.", rubric),
    written("communication", "Explain a technical issue", "Explain join multiplication to a nontechnical manager in under 120 words, including an example and repair.", "A payment can appear once for each actor in a film. A 10-unit payment linked to three actors becomes 30 when summed after that join. Count payment revenue before adding actor information, then reconcile to source payments. This fixes counting, not necessarily every business definition.", rubric),
    written("communication", "Prepare an interview story", "Write a 90-second story about one real project. Separate your contribution, evidence, constraints, and what you would improve.", "Use a specific real situation and task, describe decisions you personally made, and report only evidenced results. Label portfolio recreations or beta work honestly. Finish with a relevant lesson and one realistic next improvement.", rubric),
  ] },
];

const pythonTrack = tracks.find(t => t.id === "python")!;
const pythonExercises: Array<[string, string, string, string]> = [
  ["Total revenue", "Return total revenue as a number in a variable named result.", "result = df['revenue'].sum()", "Aggregate all records, including legitimate equal amounts."],
  ["Revenue by region", "Return a dict mapping region to total revenue in result. Do not assume a fixed set of region names.", "result = df.groupby('region')['revenue'].sum().to_dict()", "Group to region grain and reconcile the total."],
  ["Keep positive sales", "Return a sorted list of order_id values with revenue strictly greater than zero in result.", "result = sorted(df.loc[df['revenue'] > 0, 'order_id'].tolist())", "Use a boolean mask and preserve all qualifying identifiers."],
  ["Weighted margin", "Return total profit divided by total revenue in result. Return None if total revenue is zero.", "revenue = df['revenue'].sum()\nresult = None if revenue == 0 else df['profit'].sum() / revenue", "Aggregate numerator and denominator separately; handle zero deliberately."],
  ["Latest order per customer", "Return a dict mapping each customer_id to the latest order_id in result. Break same-date ties using the larger order_id.", "latest = df.sort_values(['order_date', 'order_id']).drop_duplicates('customer_id', keep='last')\nresult = dict(zip(latest['customer_id'], latest['order_id']))", "Sort deterministically before selecting the last row per customer."],
  ["Distinct customer counts", "Return a dict mapping region to its number of distinct customer_id values in result.", "result = df.groupby('region')['customer_id'].nunique().to_dict()", "Customers can place several orders; count distinct entities, not transactions."],
];
pythonTrack.exercises = pythonExercises.map(([title, prompt, solution, explanation], i) => ({ id: `python-${i + 1}`, skillId: "python", title, prompt: `${prompt}\n\nThe runner provides pandas as pd and a DataFrame df with order_id, customer_id, region, order_date, revenue, profit. Your code is checked against two synthetic datasets, including ties, repeated values, and zero-total cases.`, kind: "python", difficulty: i < 2 ? "Foundation" : "Applied", minutes: 12, starter: "# pandas is available as pd; inspect df, then assign result.\nprint(df.head())\nresult = None", solution, explanation, hints: ["Inspect columns and define the output type: scalar, sorted list, or dict.", explanation, "Test the answer on a tiny dataset with duplicate customers and a zero denominator."], rubric: [] }));

export const curriculum = tracks;
export const allExercises = tracks.flatMap(t => t.exercises);
export function getTrack(id: string) { return tracks.find(track => track.id === id); }
export function getExercise(id: string) { return allExercises.find(exercise => exercise.id === id); }

export interface LessonGuide {
 goal: string; question: string; answer: string; steps: [string,string,string]; trap: string; practiceTitle: string;
}

// Original teaching notes, grounded in the official sources linked on each lesson.
// A guide links one concrete task; reading alone never awards practice credit.
const lessonGuides: Record<string, LessonGuide[]> = {
 sql: [
  {goal:'Keep entities with no matches without accidentally counting them as events.',question:'A customer has no payments. After a LEFT JOIN, does COUNT(*) return 0 or 1 for that customer?',answer:'1: the left join preserves a row with null payment columns. COUNT(payment_id) returns 0 because it ignores nulls.',steps:['Start at customer grain: every customer must appear, including non-payers. Put customer on the left of the join.','Match payment.customer_id to customer.customer_id. A customer with two payments now occupies two joined rows; a non-payer occupies one null-extended row.','Group by customer_id to return to customer grain. Count the payment key, not the joined rows. Test both customers before trusting a total.'],trap:'Putting payment.amount > 0 in WHERE removes null-extended rows. If you need every customer, place that condition in ON or define a conditional aggregate.',practiceTitle:'Films without inventory'},
  {goal:'Calculate a monthly comparison after choosing the correct grouping level.',question:'If the only observed months are January and March, what does LAG return for March?',answer:'January. LAG follows the available ordered rows; it does not invent February. Add a month calendar if missing months should count as zero.',steps:['Reduce payment transactions to one row per month with date_trunc and SUM. Retain the month as a date, not a display label.','Apply LAG to the monthly result ordered by month. The window retains each monthly row while adding a previous value.','For percentage change, divide the difference by NULLIF(previous_revenue, 0). Decide whether missing months and no prior period mean blank or zero.'],trap:'LAG(SUM(amount)) and LAG(amount) answer different questions when the input is still at transaction grain.',practiceTitle:'Running and month-over-month revenue'},
  {goal:'Find and repair a revenue total inflated by a many-to-many join.',question:'Two genuine payments are both 4.99. Will SUM(DISTINCT amount) preserve the correct total?',answer:'No. It returns 4.99 instead of 9.98. Distinct values are not the same as distinct payment events.',steps:['Calculate SUM(amount) directly from payment as an independent baseline. Record which payments the business definition includes.','Trace payment → rental → inventory → film. Joining film_actor adds one copy of a payment per actor; the payment key no longer stays unique.','Aggregate revenue per film before joining independently aggregated actor counts. Reconcile the final revenue to the baseline and include a multi-actor film.'],trap:'A second total using the same faulty join is not an independent check.',practiceTitle:'Revenue multiplication'},
 ],
 modeling: [
  {goal:'Choose a fact grain that supports the requested product-level analysis.',question:'An order contains three products. Can one order-level row preserve a different discount for each product?',answer:'Not without another structure. Use one row per order line when quantity and discount belong to individual products.',steps:['Choose the process: product sales. Write “one row represents one order line” before naming tables.','Put quantity and net amount on the line fact. Add date, customer and product keys for the ways users need to group and filter.','Check that order_line_key is unique. Keep daily stock in a separate snapshot fact so every sales line does not repeat the balance.'],trap:'A table that mixes order totals and line amounts makes normal SUM operations unsafe.',practiceTitle:'Choose the fact grain'},
  {goal:'Attribute a sale to the customer segment that was valid when it happened.',question:'A customer changes from SMB to Enterprise on March 1. Which version should a February 28 sale use?',answer:'The SMB version. Match the event time to the dimension interval, not the current customer row.',steps:['Keep the natural customer ID to identify the entity; assign a new surrogate key to each historical version.','Close the old version at March 1 and start the new one at March 1. Use inclusive start and exclusive end to avoid overlap.','Resolve the fact to exactly one version at its event time. Test both the boundary date and late-arriving February facts.'],trap:'Joining facts to the latest customer row silently rewrites history.',practiceTitle:'Historical segment'},
  {goal:'Recompute a combined ratio using its actual numerator and denominator.',question:'Store A converts 1/2 and Store B converts 90/100. Is their combined rate 70%?',answer:'No. The combined rate is 91/102, about 89.2%. Averaging 50% and 90% gives both stores equal weight.',steps:['Identify the additive ingredients: converted sessions and eligible sessions. Preserve both in the model.','Aggregate numerator and denominator at the requested date, region or product level before dividing.','For inventory balances, use an agreed point-in-time or average balance. Summing snapshots across days measures a different quantity.'],trap:'A percentage displayed on each source row is rarely a measure you can safely sum or average.',practiceTitle:'Aggregate a ratio'},
 ],
 etl: [
  {goal:'Separate source fidelity, cleaning and business rules in a traceable pipeline.',question:'An order amount arrives as text with an invalid value. Should raw data be overwritten with the cleaned amount?',answer:'Keep the raw record. Convert in staging, capture the rejected value and reason, then publish valid business records.',steps:['Land the original batch with source and ingestion timestamps. This lets you reproduce a problem without requesting another extract.','Standardize types and keys in staging. Count rejected rows and deduplicate under an explicit ordering rule.','Build facts and dimensions at their declared grains. Reconcile source counts and amounts to published totals, accounting for rejected records.'],trap:'A green job status does not explain why 12% of source rows disappeared.',practiceTitle:'Design quality checks'},
  {goal:'Design an incremental load that is safe to retry and captures late corrections.',question:'A load commits 100 records, then loses its connection before acknowledging success. What must a retry do?',answer:'Upsert the same stable business keys so the final state stays the same. Advance the watermark only with a successful publication.',steps:['Read updated_at from a small overlap before the last successful watermark so late updates can be replayed.','Choose the newest version per stable key; upsert in a transaction. A duplicate delivery must not create another business event.','Commit publication and success state consistently. Test replaying the same batch twice and correcting yesterday’s order today.'],trap:'Filtering only on order_date misses edits to old orders; appending the overlap duplicates them.',practiceTitle:'Safe retry'},
  {goal:'Distinguish a valid quiet day from a pipeline that silently dropped data.',question:'Tuesday revenue is zero and the load reports success. Is retrying the dashboard refresh the first useful check?',answer:'First trace the source and each pipeline stage: freshness, extracted rows, rejects, date boundaries and published totals. Refreshing a broken result repeats it.',steps:['Establish impact and last known good data. Check whether Tuesday exists in the source and whether the source itself is fresh.','Compare counts at extraction, staging and publication. Inspect timezone filters and rejected amounts rather than debugging charts first.','Replay the affected window after fixing the cause. Reconcile counts and totals, then communicate the recovered period and prevention.'],trap:'Alerting on every new category hides more serious failures in noise. Set blocking checks around grain and required data.',practiceTitle:'Reconcile a missing day'},
 ],
 powerbi: [
  {goal:'Make a product slicer filter sales through one clear relationship.',question:'ProductKey repeats in Product. Can that column safely be the “one” side of a one-to-many relationship?',answer:'No. Deduplicate or repair the dimension first. A relationship does not repair incorrect keys or source grain.',steps:['Check ProductKey uniqueness in Product and the intended transaction grain in Sales before creating a visual.','Connect Product[ProductKey] 1 → * Sales[ProductKey], with Product filtering Sales. Add an explicit Revenue = SUM(Sales[Revenue]) measure.','Use a table with product and revenue. Test a single product, all products and an unmatched fact key, then reconcile to the source.'],trap:'Enabling bidirectional filtering everywhere can create ambiguous paths and surprising totals.',practiceTitle:'Filter direction'},
  {goal:'Explain which filters a category-share denominator removes and retains.',question:'A user selects January and Bikes. Should REMOVEFILTERS(Product) also remove January?',answer:'No, assuming Date is a separate dimension. It removes Product filters while the Date selection still limits the calculation.',steps:['Start with Revenue under the current slicers. For January/Bikes, the numerator is January bike revenue.','Evaluate CALCULATE([Revenue], REMOVEFILTERS(Product)). The denominator becomes January revenue across products, not all-time revenue.','Use DIVIDE and test one category, multiple categories and grand total. Explain the Product-dimension assumption and zero-denominator behavior.'],trap:'Removing filters from the whole fact table may remove more context than the business definition intends.',practiceTitle:'DAX context walkthrough'},
  {goal:'Validate a date-based measure before putting it on a report.',question:'Is a table containing only dates on which a sale occurred a complete date dimension?',answer:'No. A dedicated date table should cover the continuous reporting period so missing days and comparisons have an explicit calendar.',steps:['Create a date dimension spanning the required period and connect it to the fact’s date column. Confirm the relationship and date-table configuration.','Place Revenue, Revenue PY and YoY % in a simple month table. Verify a small known month before using visuals.','Check no-prior-year periods, empty slices and totals. Keep missing comparison periods blank unless the metric contract explicitly says otherwise.'],trap:'A percentage total is evaluated in total filter context; it is not necessarily the sum or average of the visible percentages.',practiceTitle:'Build a sales dashboard'},
 ],
 excel: [
  {goal:'Turn a repeated cleanup into a refreshable, inspectable query.',question:'You manually fix ten cells after each CSV import. What happens when the file refreshes tomorrow?',answer:'Those edits are not a repeatable transformation. Put the rule in Power Query and keep invalid values visible for review.',steps:['Keep an unmodified source and set column types deliberately. Distinguish a missing value from a conversion error.','Name each cleanup step after its purpose. Filter or quarantine errors using an explicit business rule.','Refresh with another batch and compare source, cleaned and rejected counts. The output should be reproducible without hand edits.'],trap:'Removing all error rows can make a report look clean while silently discarding revenue.',practiceTitle:'Refreshable sales workbook'},
  {goal:'Check lookup keys before trusting a matched value.',question:'A product lookup key occurs twice with two prices. Does the first returned value prove the lookup is correct?',answer:'No. The lookup rule is ambiguous. Repair or explicitly resolve duplicate keys before using the result.',steps:['Identify whether a lookup should be one-to-one or many-to-one. Check uniqueness on the reference side.','Use an explicit missing-value outcome and inspect unmatched rows rather than hiding all errors.','Reconcile row counts after merging. A lookup should not increase the number of sales rows when one result per sale is intended.'],trap:'IFERROR(..., 0) merges missing data, bad types and real zeros into one indistinguishable value.',practiceTitle:'Investigate a merge'},
  {goal:'Explain an aggregate result and prove its source range is complete.',question:'A pivot total looks plausible. What happens if the source range stops before the latest imported rows?',answer:'The pivot can be internally consistent but incomplete. Use a structured table or refreshable query and reconcile against the full source.',steps:['Use a proper table with stable headers and types. Check that newly imported records enter the source automatically.','Build the summary at the intended grouping grain. Calculate weighted rates from totals, not an average of row percentages.','Refresh, test a known slice and reconcile the grand total. Document exclusions beside the output.'],trap:'A formatting fix cannot repair an incomplete source range or a duplicated lookup.',practiceTitle:'Formula audit'},
 ],
 qlik: [
  {goal:'Spot an accidental association before it affects selections.',question:'Customer and Product both have a field named Name. Does Qlik know these names represent different things?',answer:'No. Matching field names create associations. Rename unrelated fields and keep only deliberate shared keys.',steps:['List the grain and intended keys of each loaded table. Treat every shared field name as a possible relationship.','Rename CustomerName and ProductName. Inspect multiple common fields for synthetic keys rather than deleting fields at random.','Trace a product selection to the expected sales rows. Explain the path in writing; this track does not execute Qlik.'],trap:'A model can load successfully and still associate unrelated names.',practiceTitle:'Unexpected association'},
  {goal:'Choose a mapping lookup without changing the sales grain.',question:'A product has no mapping entry. What should ApplyMap return?',answer:'Choose and specify a fallback such as Unknown. An explicit default distinguishes unmapped records from genuine categories.',steps:['Build a two-column mapping table with a deliberate key-to-value rule. Resolve duplicate mapping keys upstream.','ApplyMap the product key while loading Sales and give an explicit Unknown default.','Count unknowns and verify the same number of sales rows before and after the load. Sketch this behavior with three records in your notes.'],trap:'An ordinary join to a duplicate reference table can multiply rows; a mapping is not a substitute for validating its key rule.',practiceTitle:'Write a mapping load'},
  {goal:'Predict which selections a set expression keeps.',question:'Year=2025 and Product=A are selected. What changes in Sum({$<Year={2026}>} Revenue)?',answer:'Year becomes 2026 while Product=A remains selected. Sum({1} Revenue) starts from the full set and ignores current selections.',steps:['State the current selection in plain language before reading the expression. Here it is 2025 and product A.','Apply the modifier only to Year; predict 2026/A. Compare that with the unmodified current-selection measure and full-set identifier 1.','Use tiny written records to calculate all three results. Label the KPI with its selection behavior.'],trap:'A fixed-year KPI that silently ignores product selection is a different metric from one that only replaces the year.',practiceTitle:'Explain selection behavior'},
 ],
 python: [
  {goal:'Inspect a DataFrame and compute a total without losing legitimate records.',question:'Two different sales both have revenue 100. Should drop_duplicates on revenue run before summing?',answer:'No. Equal values can be legitimate separate events. Deduplicate by the actual business key under an explicit rule.',steps:['Inspect df.head(), df.dtypes and df.isna().sum() before assuming revenue is numeric and complete.','Sum revenue across the intended eligible rows. Assign the scalar to result so the checker can compare actual output.','Test a repeated amount and missing value deliberately. Distinguish library null behavior from the business rule you need.'],trap:'A remembered hardcoded total can pass one dataset and fail the next. The runner checks two datasets.',practiceTitle:'Total revenue'},
  {goal:'Group data to region grain without confusing sales and customer counts.',question:'One customer has three orders in a region. Does counting rows tell you the number of customers?',answer:'No. Count distinct customer_id when the question asks for customers; count rows for order-level events.',steps:['Name the requested output grain and metric: one value per region, with total revenue or distinct customers as specified.','Use groupby on region and select the appropriate aggregation. Validate lookup merges with many_to_one when that is the relationship.','Reconcile totals and inspect unmatched keys. Return a dict keyed by the observed regions, without hardcoding region names.'],trap:'A many-to-many merge can inflate grouped revenue even when the groupby itself is correct.',practiceTitle:'Revenue by region'},
  {goal:'Write a ratio that behaves deliberately when its denominator is zero.',question:'One order has 1 profit on 10 revenue, another has 90 on 100. Is their combined margin 50%?',answer:'No. Use 91/110, about 82.7%. Averaging the two order margins gives the small order too much weight.',steps:['Compute total profit and total revenue separately. Name the return type and missing-value rule before writing the division.','Return None when total revenue is zero; otherwise divide total profit by total revenue. Assign the value to result.','Test the normal case and a zero-total case. The second fixture includes counterexamples so a plausible first result is not enough.'],trap:'Suppressing a zero-division error with an arbitrary zero can imply a measured 0% margin where the ratio is undefined.',practiceTitle:'Weighted margin'},
 ],
 metrics: [
  {goal:'Write a metric definition that two developers could implement consistently.',question:'“Activation increased” uses accounts in the numerator and users in the denominator. Is the rate interpretable?',answer:'The entities do not align. Define one eligible population, event rule and observation window before calculating a rate.',steps:['Choose the entity, for example a newly created account, and an event that demonstrates a completed useful workflow.','Define seven days of observation, eligibility, exclusions, timezone and deduplication. Exclude accounts too new to finish the window.','Pair activation with a quality guardrail such as failed runs or low-rated results. Include a tiny example of qualifying and excluded accounts.'],trap:'A denominator that changes definition between weeks can create an apparent improvement without better behavior.',practiceTitle:'Define an activation metric'},
  {goal:'Separate an observed effect from a supported causal claim.',question:'Conversion rises from 5% to 6%. Is that one percentage point or a 1% relative increase?',answer:'One percentage point and 20% relative. Neither number alone proves a reliable treatment effect.',steps:['Report the counts and absolute difference first: 50/1000 versus 60/1000, a one-point difference.','Check randomization, exposure, tracking, duration and uncertainty before attributing the difference to a change.','Compare the practical value of the effect with guardrails. State what evidence would change the rollout decision.'],trap:'A p-value is not the probability that the hypothesis is true, and an observed lift alone does not establish causality.',practiceTitle:'Relative and absolute lift'},
  {goal:'Make a dashboard comparison clear, accessible and honest.',question:'A bar grows from 100 to 101, but its axis starts at 99. What visual impression does that create?',answer:'It exaggerates a small change because bar length encodes magnitude. Use a zero baseline for bars or another clearly labeled comparison.',steps:['Name the decision and the comparison: time trend, category difference or relationship. Choose the chart for that task.','Label units, complete periods and freshness. Use text or symbols as well as color to communicate status.','Write a takeaway grounded in the result, then show the evidence and a useful drill-down. Test whether the title overstates the data.'],trap:'Comparing a partial current month with a complete prior month can manufacture an apparent decline.',practiceTitle:'Dashboard critique'},
 ],
 'git-ai': [
  {goal:'Review the exact changes that will enter a commit.',question:'Does git diff show changes that are already staged?',answer:'By default it shows unstaged changes. Use git diff --cached to inspect the staged snapshot before committing.',steps:['Read git status and git diff to understand the working tree. Stage only the files tied to the intended change.','Inspect git diff --cached for unrelated edits, generated files and credentials. A focused diff makes the behavior easier to review.','Commit with a message explaining the outcome and record checks that test the actual failure mode.'],trap:'A branch does not back up uncommitted work by itself.',practiceTitle:'Review the staged snapshot'},
  {goal:'Ask AI for a change whose correctness can be independently checked.',question:'An assistant writes a convincing explanation of a revenue fix. What evidence is still missing?',answer:'Executed checks against independent counterexamples and reconciliation to a known source. Confidence of wording does not validate code.',steps:['Give the goal, schema, constraints and expected behavior. Include the payment grain and a customer with no payments.','Ask for a minimal change and checks for duplicated joins, equal-valued genuine payments and tied ranks.','Run the checks and inspect the diff yourself. Keep private data and credentials out of public prompts.'],trap:'Testing the generated query against another query with the same join error can confirm the same mistake twice.',practiceTitle:'Write a useful AI prompt'},
  {goal:'Undo a shared mistake while preserving the team’s history.',question:'A bad commit is already shared. Is force-resetting the branch the safest default recovery?',answer:'Usually use git revert to record an inverse commit. Rewriting shared history needs explicit coordination.',steps:['Establish whether the commit is shared and which later work depends on it. Preserve current work before recovery.','Use revert for a history-preserving undo, then resolve any conflict by understanding both intended behaviors.','Run the checks that originally exposed the issue and describe the resulting behavior and any remaining limitation.'],trap:'Choosing one conflict side blindly can delete a valid fix even when the resulting file compiles.',practiceTitle:'Undo a shared commit'},
 ],
 communication: [
  {goal:'Turn “build a dashboard” into a decision and acceptance examples.',question:'A manager asks which store is best. Can you start by ranking revenue without clarifying anything?',answer:'Propose revenue as a default, but confirm the decision and attribution first. Margin, growth and utilization may give different answers.',steps:['Ask who will decide what, how often, and what action could change based on the result.','Clarify the metric, period, population and store attribution. Show two alternatives with their business consequences.','Write an acceptance example using a few records. Confirm that the example matches the intended decision before implementing.'],trap:'A correct calculation can still answer the wrong business question.',practiceTitle:'Clarify store performance'},
  {goal:'Explain a technical defect through its business consequence.',question:'Which is clearer for a manager: “join fanout” or “one payment was counted once for every actor”?',answer:'Use the second explanation and a small number example, then describe how the repaired total was checked.',steps:['Lead with the finding: revenue was overstated. State the affected result rather than the sequence of debugging commands.','Show a 10-unit payment linked to three actors becoming 30. Explain that counting it before adding actor information repairs duplication.','Describe the independent reconciliation and its limits. Synthetic test success is not evidence of production savings.'],trap:'Adding an unsupported impact number makes an otherwise credible explanation weaker.',practiceTitle:'Explain a technical issue'},
  {goal:'Tell a credible project story without inventing business impact.',question:'A portfolio dashboard used synthetic data. Can its story claim it saved a real company money?',answer:'No. Describe what you built and verified, label the data, and discuss the decision it could support.',steps:['Choose one real project and give its context, your responsibility and the constraint you faced.','Explain a decision you personally made and the alternative you rejected. Keep the mechanism connected to the user’s problem.','Report observed evidence, name the limits and finish with one realistic improvement. Practice the story in about 90 seconds.'],trap:'A list of tools does not explain your contribution or judgment.',practiceTitle:'Prepare an interview story'},
 ],
};

export function getLessonGuide(lessonId:string) {
 const track = tracks.find(item=>item.lessons.some(lesson=>lesson.id===lessonId));
 if(!track) return undefined;
 const guide = lessonGuides[track.id]?.[track.lessons.findIndex(lesson=>lesson.id===lessonId)];
 if(!guide) return undefined;
 return {...guide, exercise:track.exercises.find(exercise=>exercise.title===guide.practiceTitle)};
}

export function recommendLesson(attempts:Attempt[]) {
 const latest = new Map<string,Attempt>();
 for(const attempt of [...attempts].sort((a,b)=>a.createdAt.localeCompare(b.createdAt))) latest.set(attempt.exerciseId,attempt);
 const sessions = tracks.flatMap(track=>track.lessons.map(lesson=>({track,lesson,guide:getLessonGuide(lesson.id)!})));
 const retry = sessions.find(session=>session.guide.exercise&&latest.get(session.guide.exercise.id)?.passed===false);
 return retry??sessions.find(session=>{const attempt=session.guide.exercise&&latest.get(session.guide.exercise.id);return !attempt||attempt.passed!==true;})??sessions[0];
}
